let customerSubmitInFlight = false;
async function submitCustomerForm(form) {
  if (customerSubmitInFlight) return;
  customerSubmitInFlight = true;
  const values = Object.fromEntries(new FormData(form).entries());
  const submit = form.querySelector('button[type="submit"]');
  const resetSubmit = () => { if (submit) { submit.disabled = false; submit.textContent = '保存'; } customerSubmitInFlight = false; };
  if (submit) { submit.disabled = true; submit.textContent = '保存中…'; }
  for (const key of ['targetCustomerYear','operatingScaleThousand','constructionArea','landReserveArea']) if (values[key] !== '') {
    const parsed = Number(values[key]);
    if (!Number.isFinite(parsed) || parsed < 0) { resetSubmit(); toast(`${key} 必须是非负数字`); return; }
    values[key] = parsed;
  }
  if (values.establishedDate && Number.isNaN(Date.parse(values.establishedDate))) { resetSubmit(); toast('成立时间格式不正确'); return; }
  const customerId = drawerState.context.customerId;
  const isEdit = customerId && /^\d+$/.test(String(customerId));
  let response;
  try {
    response = await fetch(isEdit ? `/api/customers/${customerId}` : '/api/customers', {method:isEdit ? 'PUT' : 'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(values)});
  } catch (error) {
    try {
      const lookup = await fetch('/api/customers');
      const rows = lookup.ok ? await lookup.json() : [];
      const existingRow = rows.find(row => String(row.name || '').trim() === String(values.name || '').trim());
      if (existingRow) response = {ok:true, json:async () => existingRow};
      else { resetSubmit(); toast('客户保存结果不确定，未发现已创建记录，请先确认后再重试'); return; }
    } catch (lookupError) { resetSubmit(); toast('客户保存结果不确定，请先查询客户列表后再重试'); return; }
  }
  const body = await response.json().catch(() => ({}));
  if (!response.ok) { resetSubmit(); toast(body.error || '客户保存失败'); return; }
  const item = {...body, id:body.id, shortName:(body.name || values.name).slice(0,6), level:body.customer_level || 'POTENTIAL', keyPersonIds:[], projectIds:[]};
  const existing = byId(customers, item.id);
  if (existing) Object.assign(existing, item); else customers.push(item);
  let verified = true;
  try {
    const verifyResponse = await fetch(`/api/customers/${body.id}`);
    if (verifyResponse.ok) {
      const verifiedBody = await verifyResponse.json();
      Object.assign(item, verifiedBody);
      if (existing) Object.assign(existing, verifiedBody); else customers[customers.length - 1] = item;
    } else verified = false;
  } catch (error) { verified = false; }
  const serial = body.customer_serial_no || item.customer_serial_no || '保持不变';
  const standaloneCreate = window.location.pathname === '/customer-create';
  closeEntryDrawer();
  resetSubmit();
  if (standaloneCreate) history.pushState({}, '', '/customer');
  render();
  toast(verified ? (isEdit ? `客户已更新，流水号 ${serial}` : `客户已创建，流水号 ${serial}`) : `客户已保存，流水号 ${serial}；列表刷新失败，请稍后重试`);
}
