async function loadSelectedCustomerProfile(customerId) { if (!customerId) return; profileWorkbenchState = { customerId, profile:null, loading:true, error:'' }; const content = document.querySelector('#profileWorkbenchContent'); if (content) content.innerHTML = profileWorkbenchContent(byId(customers, customerId), null, profileWorkbenchState); try { const response = await fetch(`/api/customers/${encodeURIComponent(customerId)}/profile`); if (response.status === 404) profileWorkbenchState = { customerId, profile:null, loading:false, error:'' }; else if (!response.ok) throw new Error('客户画像加载失败，请稍后重试'); else profileWorkbenchState = { customerId, profile:await response.json(), loading:false, error:'' }; } catch (error) { profileWorkbenchState = { customerId, profile:null, loading:false, error:error.message || '客户画像加载失败' }; } const root = document.querySelector('#profileWorkbenchContent'); if (root) { root.innerHTML = profileWorkbenchContent(byId(customers, customerId), profileWorkbenchState.profile, profileWorkbenchState); bindProfileWorkbench(); } }
