async function saveCustomerDevelopment() { const select = document.querySelector('#developmentCustomerSelect'); const customerId = select?.value; const name = document.querySelector('#developmentName')?.value.trim(); const stageCode = document.querySelector('#developmentStage')?.value || 'AT1'; const errorNode = document.querySelector('#developmentSaveError'); if (!customerId) { if (errorNode) errorNode.textContent = '请选择客户'; return; } if (!name) { if (errorNode) errorNode.textContent = '请输入开发记录名称'; return; } const button = document.querySelector('#developmentSave'); if (button) { button.disabled = true; button.textContent = '保存中…'; } try { const response = await fetch('/api/customer-developments', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({customerId:Number(customerId), name, stageCode, owner:'李盛云'})}); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error || '客户开发保存失败'); developmentWorkbenchState.customerId = Number(customerId); developmentWorkbenchState.items = []; toast('客户开发已保存'); history.pushState({}, '', `/customer-development/${customerId}`); render(); } catch (error) { if (errorNode) errorNode.textContent = error.message || '客户开发保存失败'; if (button) { button.disabled = false; button.textContent = '保存客户开发'; } } }
function bindDevelopmentWorkbench() { const select = document.querySelector('#developmentCustomerSelect'); const search = document.querySelector('#developmentCustomerSearch'); search?.addEventListener('input', event => { const query = event.target.value.trim().toLowerCase(); [...(select?.options || [])].forEach(option => { option.hidden = Boolean(query) && !option.textContent.toLowerCase().includes(query); }); }); select?.addEventListener('change', event => { developmentWorkbenchState.customerId = event.target.value; const customer = byId(customers, event.target.value); const input = document.querySelector('#developmentName'); if (input && customer && !input.value) input.value = `${customer.name}客户开发`; }); document.querySelector('#developmentSave')?.addEventListener('click', saveCustomerDevelopment); }
function customerDevelopmentWorkbenchDetailPage(customerId = '') { const customer = byId(customers, customerId) || customers.find(item => String(item.id) === String(customerId)); const item = developmentWorkbenchState.items.find(row => String(row.customer_id || row.customerId) === String(customerId)); setTimeout(() => { if (!item && customerId) loadDevelopmentDetail(customerId); else { bindAt1DevelopmentForm(); syncDevelopmentStagePanels(item); } }, 0); if (!customer) return shell('客户开发', '<div class="panel profile-workbench-state">客户不存在或客户主数据尚未加载。</div>'); const stage = developmentWorkbenchState.focusStage || item?.current_stage_code || item?.currentStage?.code || customer.developmentStage || 'AT1'; return shell('客户开发', `<div class="page-head"><div><a class="back-link" href="/customer-development">← 返回客户开发</a><div class="tag purple">销售工作台 · 客户开发</div><h1>${esc(customer.name)} 客户开发</h1><p>customer_id：${esc(customer.id)} · 客户流水号：${esc(customer.customer_serial_no || '未生成')} · ${esc(customer.customer_region || customer.region || '未填写区域')}</p></div><span class="tag ${item ? 'green' : 'orange'}">${item ? '已持久化关联' : '正在加载…'}</span></div><section class="panel"><div class="section-title"><h3>客户开发阶段</h3><span>当前录入：${esc(stage)}</span></div><div class="profile360-at-line">${['AT1','AT2','AT3','AT4','AT5','AT6'].map(code => `<div class="profile360-at-step ${code === stage ? 'current' : ''}"><span>${code}</span><strong>${code}</strong><small>${({AT1:'客户立项',AT2:'需求与关系引导',AT3:'招投标',AT4:'履约交付',AT5:'履约服务',AT6:'复盘沉淀'})[code]}</small></div>`).join('')}</div></section><section class="panel"><div class="section-title"><h3>客户主数据</h3><span>customer_id 关联</span></div><div class="development-detail-summary"><div><span>客户</span><strong>${esc(customer.name)}</strong></div><div><span>客户流水号</span><strong>${esc(customer.customer_serial_no || '未生成')}</strong></div><div><span>终端客户编码</span><strong>${esc(customer.terminal_customer_code || '尚未分配')}</strong></div><div><span>开发记录</span><strong>${esc(item?.name || '加载中')}</strong></div></div></section>${item ? at1DevelopmentPanel(item, customer) : '<section class="panel profile-workbench-state">正在加载 AT1 数据…</section>'}`); }

function at1Field(item, code) { return item?.atData?.fields?.find(field => field.stage_code === 'AT1' && field.field_code === code)?.value ?? ''; }
