async function saveAt1Fields(developmentId, form) { const fields = [...form.querySelectorAll('[data-at1-field]:not([data-at1-field^="__"])')].map(node => ({stageCode:'AT1', fieldCode:node.dataset.at1Field, value:node.value === '' ? null : node.value})); const response = await fetch(`/api/customer-developments/${developmentId}/fields`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({fields})}); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error || 'AT1 字段保存失败'); return body; }
async function bindAt1DevelopmentForm() { const form = document.querySelector('#at1DevelopmentForm'); if (!form || form.dataset.bound === '1') return; form.dataset.bound = '1'; const item = developmentWorkbenchState.items.find(row => String(row.id) === String(form.closest('.at1-development-panel')?.dataset.developmentId)) || developmentWorkbenchState.items.find(row => row.atData); const developmentId = item?.id; if (!developmentId) return; document.querySelector('#at1AddPerson')?.addEventListener('click', async () => { const personId = document.querySelector('[data-at1-field="__person_id"]')?.value; if (!personId) return toast('请选择人员'); try { const response = await fetch(`/api/customer-developments/${developmentId}/people`, {method:'PUT', headers:{'Content-Type':'application/json'}, body:JSON.stringify({stageCode:'AT1', personId:Number(personId), roleCode:document.querySelector('[data-at1-field="__person_role"]')?.value || '', responsibility:document.querySelector('[data-at1-field="__person_responsibility"]')?.value || '', enteredAt:document.querySelector('[data-at1-field="__person_entered_at"]')?.value || null})}); if (!response.ok) throw new Error((await response.json()).error || '人员保存失败'); toast('参与人员已保存'); loadDevelopmentDetail(item.customer_id); } catch (error) { toast(error.message || '人员保存失败'); } }); document.querySelector('#at1AddAttachment')?.addEventListener('click', async () => { const evidenceId = document.querySelector('[data-at1-field="__evidence_id"]')?.value; const attachmentType = document.querySelector('#at1AttachmentType')?.value; if (!evidenceId) return toast('请输入现有证据 ID'); try { const response = await fetch(`/api/customer-developments/${developmentId}/attachments`, {method:'PUT', headers:{'Content-Type':'application/json'}, body:JSON.stringify({stageCode:'AT1', attachmentType, evidenceId:Number(evidenceId)})}); if (!response.ok) throw new Error((await response.json()).error || '附件关联失败'); toast('附件已关联'); loadDevelopmentDetail(item.customer_id); } catch (error) { toast(error.message || '附件关联失败'); } }); form.addEventListener('submit', async event => { event.preventDefault(); const button = document.querySelector('#at1Save'); const errorNode = document.querySelector('#at1SaveError'); button.disabled = true; button.textContent = '保存中…'; try { await saveAt1Fields(developmentId, form); toast('AT1 客户立项已保存'); await loadDevelopmentDetail(item.customer_id); } catch (error) { if (errorNode) errorNode.textContent = error.message || 'AT1 保存失败'; button.disabled = false; button.textContent = '保存 AT1'; } }); }
async function loadDevelopmentDetail(customerId) { try { const response = await fetch(`/api/customer-developments?customerId=${encodeURIComponent(customerId)}`); if (!response.ok) throw new Error('客户开发详情加载失败'); const rows = await response.json(); const detailed = await Promise.all(rows.map(async row => { const detailResponse = await fetch(`/api/customer-developments/${encodeURIComponent(row.id)}`); return detailResponse.ok ? detailResponse.json() : row; })); developmentWorkbenchState.items = [...developmentWorkbenchState.items.filter(item => String(item.customer_id || item.customerId) !== String(customerId)), ...detailed]; render(); } catch (error) { developmentWorkbenchState.error = error.message || '客户开发详情加载失败'; render(); } }
