function at3DevelopmentPanel(item, customer) { const productOptions = [...new Set(opportunities.map(row => row.businessType || row.business_type).filter(Boolean))]; const metric = code => item.atData?.metrics?.find(row => row.metric_code === code); const field = (label, code, type = 'text', readonly = false) => `<label class="entry-field"><span>${label}</span><input data-at3-field="${code}" type="${type}" value="${esc(at3Field(item, code))}" ${readonly ? 'readonly' : ''} /></label>`; const select = (label, code, options) => `<label class="entry-field"><span>${label}</span><select data-at3-field="${code}">${options.map(row => `<option value="${esc(row[0])}" ${String(row[0]) === String(at3Field(item, code)) ? 'selected' : ''}>${esc(row[1])}</option>`).join('')}</select></label>`; const attachments = (item.atData?.attachments || []).filter(row => row.stage_code === 'AT3'); const attachmentTypes = [['commercial_bid','商务标'],['technical_bid','技术标'],['returned_bid','回标文件'],['solution_form','解决方案表单'],['award_notice','中标通知书'],['contract_text','合同文本'],['contract_distribution','合同分发文件'],['project_list','项目清单'],['product_list','产品清单'],['ppt_presentation','PPT 宣导文件'],['other','其他']]; const regions = [...new Set([customer.customer_region, customer.region, ...customers.map(row => row.customer_region || row.region)].filter(Boolean))]; return `<section class="panel at3-development-panel"><div class="section-title"><h3>AT3 招投标</h3><span>不自动推进阶段</span></div><form id="at3DevelopmentForm"><div class="at1-field-group"><h4>招投标结果与模式</h4><div class="entry-grid">${select('中标结果','award_result',[['','请选择'],['完全中标','完全中标'],['部分中标','部分中标'],['未中标','未中标']])}${field('实际招采模式','actual_procurement_mode')}${select('中标覆盖范围','award_coverage_scope',[['','请选择'],['全国','全国'],['区域','区域']])}${select('中标覆盖省/市','award_province',[['','请选择'],...regions.map(value => [value,value])])}${field('中标覆盖城市','award_city')}${field('集采周期（开始年份）','procurement_cycle_start','number')}${field('集采周期（合作完结年份）','procurement_cycle_end','number')}${field('中标竞品','winning_competitor')}</div></div><div class="at1-field-group"><h4>金额与业务指标</h4><div class="entry-grid">${field('客户采购总量（千元）','customer_purchase_total','number',true)}${field('立邦签约总额（千元）','nippon_signed_total','number',true)}<label class="entry-field"><span>总市占率</span><input value="${metric('total_market_share')?.value == null ? '暂无已确认公式' : `${(Number(metric('total_market_share').value) * 100).toFixed(2)}%`}" readonly /></label>${field('投标总金额（千元）','bid_total_amount','number')}${field('立邦签约额（千元）','nippon_signed_amount','number',true)}</div></div><div class="at1-field-group"><h4>产品与业务信息</h4><div class="entry-grid">${field('基材/建筑环境','substrate')}${field('财务意见','finance_opinion')}${field('法务意见','legal_opinion')}${select('M01（商机业务类型字典）','m01',[['','请选择'],...productOptions.map(value => [value,value])])}${select('M04（商机业务类型字典）','m04',[['','请选择'],...productOptions.map(value => [value,value])])}</div></div><div class="at1-field-group"><h4>中标与附件资料</h4><div id="at3AttachmentRows">${attachments.map(row => `<div class="at1-person-row"><span>${esc(row.attachment_type)} · ${esc(row.file_name || `证据 #${row.evidence_id}`)}</span></div>`).join('') || '<div class="profile-workbench-state">暂无 AT3 附件记录</div>'}</div><div class="entry-grid"><label class="entry-field"><span>附件类型</span><select id="at3AttachmentType">${attachmentTypes.map(row => `<option value="${row[0]}">${row[1]}</option>`).join('')}</select></label>${field('现有证据 ID','__at3_evidence_id','number')}<button type="button" class="secondary" id="at3AddAttachment">关联附件</button></div></div><div class="entry-form-foot"><span id="at3SaveError">签约金额和总市占率遵循已确认口径；未确认时保持不可用</span><button type="submit" class="primary" id="at3Save">保存 AT3</button></div></form></section>`; }
async function saveAt3Fields(item, form) { const fields = [...form.querySelectorAll('[data-at3-field]:not([data-at3-field^="__"])')].map(node => ({stageCode:'AT3', fieldCode:node.dataset.at3Field, value:node.value === '' ? null : node.value})); const response = await fetch(`/api/customer-developments/${item.id}/fields`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({fields})}); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error || 'AT3 字段保存失败'); return body; }
function bindAt3DevelopmentForm(item) { const form = document.querySelector('#at3DevelopmentForm'); if (!form || form.dataset.bound === '1' || !item?.id) return; form.dataset.bound = '1'; form.addEventListener('submit', async event => { event.preventDefault(); const button = document.querySelector('#at3Save'); const errorNode = document.querySelector('#at3SaveError'); button.disabled = true; button.textContent = '保存中…'; try { await saveAt3Fields(item, form); toast('AT3 招投标已保存'); await loadDevelopmentDetail(item.customer_id); } catch (error) { errorNode.textContent = error.message || 'AT3 保存失败'; button.disabled = false; button.textContent = '保存 AT3'; } }); document.querySelector('#at3AddAttachment')?.addEventListener('click', async () => { const evidenceId = document.querySelector('[data-at3-field="__at3_evidence_id"]')?.value; const attachmentType = document.querySelector('#at3AttachmentType')?.value; if (!evidenceId) return toast('请输入现有证据 ID'); const response = await fetch(`/api/customer-developments/${item.id}/attachments`, {method:'PUT', headers:{'Content-Type':'application/json'}, body:JSON.stringify({stageCode:'AT3', attachmentType, evidenceId:Number(evidenceId)})}); if (!response.ok) return toast((await response.json()).error || '附件关联失败'); toast('AT3 附件已关联'); loadDevelopmentDetail(item.customer_id); }); }
const at3Observer = new MutationObserver(() => { const root = document.querySelector('.at2-development-panel'); if (!root || document.querySelector('.at3-development-panel')) return; const item = developmentWorkbenchState.items.find(row => row.atData); if (!item) return; root.insertAdjacentHTML('afterend', at3DevelopmentPanel(item, byId(customers, item.customer_id) || customers[0])); bindAt3DevelopmentForm(item); }); at3Observer.observe(document.documentElement, {childList:true, subtree:true});

// 客户开发采用单阶段录入：当前阶段只展示对应字段，保存后自动切换录入视图。
function syncDevelopmentStagePanels(item) {
  const active = developmentWorkbenchState.focusStage || item?.current_stage_code || item?.currentStage?.code || 'AT1';
  const panels = [['AT1', '.at1-development-panel'], ['AT2', '.at2-development-panel'], ['AT3', '.at3-development-panel']];
  panels.forEach(([stage, selector]) => document.querySelectorAll(selector).forEach(panel => {
    panel.hidden = stage !== active;
    panel.dataset.developmentStagePanel = stage;
  }));
  const order = ['AT1', 'AT2', 'AT3', 'AT4', 'AT5', 'AT6'];
  const activeIndex = order.indexOf(active);
  document.querySelectorAll('.profile360-at-step').forEach(step => {
    const code = step.querySelector('strong')?.textContent;
    const index = order.indexOf(code);
    step.classList.toggle('done', index >= 0 && index < activeIndex);
    step.classList.toggle('current', code === active);
    const marker = step.querySelector('span');
    if (marker && index >= 0 && index < activeIndex) marker.textContent = '✓';
  });
}
function focusDevelopmentStage(item, stageCode) {
  if (!['AT1', 'AT2', 'AT3'].includes(stageCode)) return;
  developmentWorkbenchState.focusStage = stageCode;
  syncDevelopmentStagePanels(item);
  document.querySelectorAll('.profile360-at-step').forEach(step => step.classList.toggle('current', step.querySelector('strong')?.textContent === stageCode));
  const stageLabel = document.querySelector('.profile360-at-line')?.parentElement?.querySelector('.section-title span');
  if (stageLabel) stageLabel.textContent = `当前录入：${stageCode}`;
  document.querySelector(`[data-development-stage-panel="${stageCode}"]`)?.scrollIntoView({behavior:'smooth', block:'start'});
}
const developmentStagePanelObserver = new MutationObserver(() => {
  const item = developmentWorkbenchState.items.find(row => row.atData) || developmentWorkbenchState.items[0];
  if (item) syncDevelopmentStagePanels(item);
});
developmentStagePanelObserver.observe(document.documentElement, {childList:true, subtree:true});
document.addEventListener('click', event => {
  const button = event.target.closest?.('#at1Save, #at2Save');
  if (!button) return;
  const item = developmentWorkbenchState.items.find(row => row.atData) || developmentWorkbenchState.items[0];
  if (!item) return;
  const nextStage = button.id === 'at1Save' ? 'AT2' : 'AT3';
  setTimeout(() => focusDevelopmentStage(item, nextStage), 900);
});
document.addEventListener('submit', event => {
  const form = event.target.closest?.('#at1DevelopmentForm, #at2DevelopmentForm');
  if (!form) return;
  const item = developmentWorkbenchState.items.find(row => row.atData);
  if (!item) return;
  const nextStage = form.id === 'at1DevelopmentForm' ? 'AT2' : 'AT3';
  setTimeout(() => focusDevelopmentStage(item, nextStage), 1200);
}, true);

// Task 3：行业语义浏览实体页统一工作区（覆盖旧版占位实现，不改变路由）。
function legacySemanticObjectsPage3() { const tabs = [['entity','实体',true],['relation','关系图谱',false],['term','术语和别名',false],['action','业务动作',false],['event','业务事件',false],['rule','业务规则',false],['process','流程与 SOP',false],['metric','指标',false],['dimension','维度',false],['target','目标与阈值',false],['analysis_model','分析模型',false],['attribution','归因因子',false],['strategy','业务策略',false]]; return shell('行业语义浏览', `<div class="page-head"><div><div class="tag blue">Ontology Management · Semantic Registry</div><h1>行业语义浏览</h1><p>统一浏览行业语义定义；实体页读取真实元数据，其余分类按实现状态展示。</p></div></div><section class="panel semantic-browser-toolbar"><div class="management-filters"><select id="semanticPresetType"><option>预置类型：行业语义</option><option>预置类型：企业标准</option><option>预置类型：CRM 通用</option></select><select id="semanticObjectDomain"><option value="">全部领域 / 行业</option></select><input id="semanticObjectSearch" placeholder="搜索名称、技术名称、编码或别名" /><button class="secondary" id="semanticObjectRefresh">刷新</button></div></section><nav class="semantic-category-tabs" aria-label="行业语义分类">${tabs.map(([key,label,implemented]) => `<button class="semantic-category-tab ${implemented ? 'active' : 'unimplemented'}" data-semantic-category="${key}">${label}${implemented ? '' : '<small>未实现</small>'}</button>`).join('')}</nav><div id="semanticCategoryState"></div><div class="two-col semantic-object-layout" id="semanticEntityWorkspace"><section><div class="section-title"><h3>实体目录</h3><span id="semanticObjectCount">加载中</span></div><div class="panel semantic-entity-list-panel"><div class="semantic-entity-list" id="semanticObjectRows"><div class="profile-empty">正在读取实体元数据…</div></div></div></section><section><div class="section-title"><h3>实体详情</h3><span>统一元数据组件 · 只读</span></div><div class="panel semantic-entity-detail-panel" id="semanticObjectDetail"><div class="profile-empty">选择左侧实体查看定义、业务边界、属性和关系。</div></div></section></div>`); }


